 24	const MQTT_HOST=process.env.MQTT_HOST||'mosquitto';
 25	const MQTT_PORT=Number(process.env.MQTT_PORT||1883);
 26	const ACTIONS=new Set([...SCENARIOS.map(s=>s[0]),...PLAYBOOKS.map(x=>'playbook:'+x.id),'cancelBlast','safety']);
 27	let currentMap='saryarka',ops=new MineOperations(MAPS[currentMap]),running=true,rate=1,connected=false;
 28	let lastPublish=0,lastError='';
 29	const broker=mqtt.connect(`mqtt://${MQTT_HOST}:${MQTT_PORT}`,{clientId:'mine-mirage-authority',reconnectPeriod:1500,connectTimeout:8000});
 30	broker.on('connect',()=>{connected=true;console.log('MQTT connected',MQTT_HOST);publish();});
 31	broker.on('reconnect',()=>{connected=false;});
 32	broker.on('offline',()=>{connected=false;});
 33	broker.on('error',e=>{lastError=String(e.message);console.error('MQTT',e.message);});
 34	function feature(value,unit){return {properties:unit?{value,unit}:{value}};}
 35	function publishTwin(id,features){
 36	  if(!connected)return;
 37	  const body={topic:`${NS}/${id}/things/twin/commands/modify`,path:'/features',value:features};
 38	  broker.publish(`telemetry/${id}`,JSON.stringify(body),{qos:1});
 39	}
 40	function publish(){
 41	  if(!connected)return;
 42	  const snap=ops.snapshot();
 43	  publishTwin('mine-01',{
 44	    state:feature(snap),
 45	    map:feature(snap.mapId),
 46	    simulation_time:feature(Math.round(snap.time*10)/10,'s'),
 47	    mined_tonnes:feature(snap.metrics.tonnes,'t'),
 48	    processed_tonnes:feature(snap.metrics.processed,'t'),
 49	    moving_trucks:feature(snap.metrics.moving),
 50	    energy:feature(snap.metrics.energyKwh??0,'kWh'),
 51	    running:feature(running),
 52	    speedup:feature(rate),
 53	    updated_at:feature(new Date().toISOString())
 54	  });
 55	  for(const t of snap.fleet){
 56	    publishTwin(t.id.toLowerCase(),{
 57	      state:feature(t.status),speed:feature(t.speed,'km/h'),
 58	      payload:feature(t.payload,'t'),fuel:feature(t.fuel,'%'),
 59	      health:feature(t.health,'%'),target:feature(t.target||''),
 60	      position:feature({x:t.position?.x||0,y:t.position?.y||0,z:t.position?.z||0})
 61	    });
 62	  }
 63	  for(const [id,a] of Object.entries(snap.assets)){
 64	    const key=a.id?.toLowerCase()||id;
 65	    publishTwin(key,{
 66	      state:feature(a.state||'idle'),
 67	      health:feature(a.health||0,'%'),
 68	      handled_tonnes:feature(a.handledTonnes||0,'t'),
