 90	function parseBody(req){return new Promise((resolve,reject)=>{const chunks=[];let size=0;req.on('data',buf=>{size+=buf.length;if(size>16384){reject(Error('payload too large'));req.destroy();return;}chunks.push(buf);});req.on('end',()=>{try{resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')||'{}'));}catch(e){reject(e)}});req.on('error',reject);});}
 91	async function getTwin(){
 92	  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),5500);
 93	  try{
 94	    const url=`${DITTO}/api/2/things/${encodeURIComponent(NS+':mine-01')}`;
 95	    const result=await fetch(url,{headers:{Authorization:AUTH,Accept:'application/json'},signal:controller.signal});
 96	    if(!result.ok)throw Error(`Ditto HTTP ${result.status}`);
 97	    const twin=await result.json();
 98	    const value=twin.features?.state?.properties?.value;
 99	    if(!value?.fleet||!value?.metrics)throw Error('Ditto twin not yet initialized by MQTT');
100	    return {snapshot:value,dittoThingId:twin.thingId,revision:twin._revision||0,updatedAt:twin.features?.updated_at?.properties?.value||null};
101	  }finally{clearTimeout(timer);}
102	}
103	async function serveFile(req,res,pathname){
104	  let decoded;
105	  try{decoded=decodeURIComponent(pathname);}catch{return json(res,400,{error:'bad path'});}
106	  const rel=decoded==='/'?'index.html':decoded.slice(1);
107	  const dest=path.resolve(WEB,rel);
108	  if(!(dest===WEB||dest.startsWith(WEB+path.sep)))return json(res,403,{error:'forbidden'});
109	  try{
110	    const stat=await fs.promises.stat(dest);
111	    if(!stat.isFile())return json(res,404,{error:'not a file'});
112	    res.writeHead(200,{'Content-Type':TYPES[path.extname(dest).toLowerCase()]||'application/octet-stream','Cache-Control':/\.(?:html|js|css)$/.test(dest)?'no-cache':'public, max-age=3600','X-Content-Type-Options':'nosniff'});
113	    fs.createReadStream(dest).pipe(res);
114	  }catch{return json(res,404,{error:'not found'});}
115	}
116	const server=http.createServer(async(req,res)=>{
117	  try{
118	    const uri=new URL(req.url||'/',`http://localhost:${PORT}`);
119	    if(req.method==='GET'&&uri.pathname==='/api/health'){
120	      return json(res,200,{service:'mine-mirage',mqttConnected:connected,map:currentMap,running,rate,lastPublish,platform:DITTO,lastError});
121	    }
122	    if(req.method==='GET'&&uri.pathname==='/api/twin'){
123	      try{return json(res,200,await getTwin());}
124	      catch(e){return json(res,503,{error:'Ditto data unavailable',detail:e.message});}
125	    }
126	    if(req.method==='POST'&&uri.pathname==='/api/command'){
127	      const {action}=await parseBody(req);
128	      if(typeof action!=='string'||!ACTIONS.has(action))return json(res,400,{error:'unknown action'});
129	      if(!connected)return json(res,503,{error:'MQTT not connected'});
130	      const applied=ops.action(action);publish();return json(res,202,{accepted:true,applied:Boolean(applied),source:'command queued to Ditto via MQTT'});
131	    }
132	    if(req.method==='POST'&&uri.pathname==='/api/control'){
133	      const body=await parseBody(req);
134	      if(body.operation==='toggle'){running=!running;}
135	      else if(body.operation==='reset'){ops=new MineOperations(MAPS[currentMap]);running=true;}
136	      else if(body.operation==='speed'&&[0.5,1,3,5].includes(body.rate)){rate=body.rate;}
137	      else if(body.operation==='map'&&MAPS[body.map]){currentMap=body.map;ops=new MineOperations(MAPS[currentMap]);running=true;}
138	      else return json(res,400,{error:'invalid control'});
139	      publish();return json(res,202,{accepted:true});
140	    }
141	    if(req.method!=='GET'&&req.method!=='HEAD')return json(res,405,{error:'method not allowed'});
142	    return serveFile(req,res,uri.pathname);
143	  }catch(e){console.error(e);return json(res,500,{error:String(e.message)});}
144	});
145	server.listen(PORT,'0.0.0.0',()=>console.log(`MINE//MIRAGE platform UI listening on ${PORT}`));

